import math

def fspl_db(f_mhz, d_km):
    # Free-space path loss, ITU-R P.525: 32.4 + 20 log10(f) + 20 log10(d)
    return 32.4 + 20 * math.log10(f_mhz) + 20 * math.log10(d_km)

def max_range_km(tx_dbm, rx_gain_dbi, sensitivity_dbm, f_mhz=2437):
    budget = tx_dbm + rx_gain_dbi - sensitivity_dbm   # loss we can afford
    return 10 ** ((budget - 32.4 - 20 * math.log10(f_mhz)) / 20)

print(f"loss at 100 m: {fspl_db(2437, 0.1):.1f} dB")
for gain in (0, 15):   # laptop antenna vs a directional antenna
    print(f"gain {gain:2d} dBi: {max_range_km(20, gain, -90):.1f} km in free space")

# loss at 100 m: 80.1 dB
# gain  0 dBi: 3.1 km in free space
# gain 15 dBi: 17.5 km in free space

