def keyspace(entropy_bytes):
    return 2 ** (8 * entropy_bytes)

rate = 10 ** 9                       # assumed guesses per second
for n in (1, 7, 16):
    keys = keyspace(n)
    years = keys / rate / (3600 * 24 * 365)
    print(f"{n:2d} bytes: {keys:.3g} keys, {years:.3g} years to try all")

#  1 bytes: 256 keys, 8.12e-15 years to try all
#  7 bytes: 7.21e+16 keys, 2.28 years to try all
