// Vulnerable (MASWE-0004): a secret compiled into the APK. An APK (Android package, the install file) is a ZIP file;
// anyone who downloads the app can unpack it and search for strings like this.
object Config { const val PAYMENTS_API_SECRET = "EXAMPLE-SECRET-1234" }

// Fixed: encrypt with an AES key that lives in the Android Keystore.
// The key material never enters the app's process and cannot be exported.
private const val ALIAS = "session_key"

private fun key(): SecretKey {
    val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
    (ks.getKey(ALIAS, null) as? SecretKey)?.let { return it }
    val gen = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
    gen.init(
        KeyGenParameterSpec.Builder(ALIAS,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .build())
    return gen.generateKey()
}

fun saveToken(prefs: SharedPreferences, token: String) {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, key())     // Keystore chooses a fresh IV
    val ct = cipher.doFinal(token.toByteArray())
    prefs.edit()
        .putString("iv", Base64.encodeToString(cipher.iv, Base64.NO_WRAP))
        .putString("token", Base64.encodeToString(ct, Base64.NO_WRAP))
        .apply()
}

