import android.os.Build
import java.time.LocalDate
import java.time.temporal.ChronoUnit

// Build.VERSION.SECURITY_PATCH is the device's security patch level,
// a date string such as "2026-10-05"
fun patchAgeDays(today: LocalDate = LocalDate.now()): Long =
    ChronoUnit.DAYS.between(LocalDate.parse(Build.VERSION.SECURITY_PATCH), today)

// Example policy: block work data on devices more than 90 days behind
fun isCompliant(maxAgeDays: Long = 90): Boolean = patchAgeDays() <= maxAgeDays
